@pytest.mark.parametrize("limit", [1, 2, 4, 5, 500])
def test_walk_includes_all_orders_sharing_a_timestamp(tied_client, limit):
    out, cursor = [], None
    pages = []
    for _ in range(10):
        q = {"limit": limit} if cursor is None else {"limit": limit, "cursor": cursor}
        response = tied_client.get("/orders", query_string=q)
        assert response.status_code == 200
        body = response.get_json()
        pages.append(len(body["orders"]))
        out += body["orders"]
        cursor = body["next_cursor"]
        if cursor is None:
            break
    else:
        raise AssertionError("too many pages")

    assert [o["id"] for o in out] == [5, 4, 3, 2, 1]
    expected = [limit] * (5 // limit) + ([5 % limit] if 5 % limit else [0])
    assert pages == expected


