def test_exact_multiple_ends_with_an_empty_page(client):
    body = client.get("/orders?limit=5").get_json()
    assert len(body["orders"]) == 5
    assert body["next_cursor"] is not None
    body = client.get("/orders", query_string={"limit": 5, "cursor": body["next_cursor"]}).get_json()
    assert body == {"orders": [], "next_cursor": None}
