import os, sqlite3, tempfile, time
from orders_service.pagination import Cursor, paginate

path=tempfile.mktemp(suffix='.db')
con=sqlite3.connect(path)
con.executescript('''
CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL, total_cents INTEGER NOT NULL, currency TEXT NOT NULL, channel TEXT NOT NULL);
CREATE INDEX orders_created_at ON orders(created_at);
CREATE INDEX orders_customer ON orders(customer_id,created_at);
''')
con.executemany("INSERT INTO orders (customer_id,created_at,status,total_cents,currency,channel) VALUES (1,'2020-01-01T00:00:00Z','paid',1,'USD','web')", [(i,) for i in range(1,100001)])
con.commit()
con.row_factory=sqlite3.Row

def split_page(cursor, limit):
    if cursor is None:
        return con.execute('SELECT id FROM orders ORDER BY created_at DESC,id DESC LIMIT ?',(limit,)).fetchall()
    rows=con.execute('SELECT id FROM orders WHERE created_at=? AND id<? ORDER BY id DESC LIMIT ?',(cursor.created_at,cursor.id,limit)).fetchall()
    if len(rows)<limit:
        rows += con.execute('SELECT id FROM orders WHERE created_at<? ORDER BY created_at DESC,id DESC LIMIT ?',(cursor.created_at,limit-len(rows))).fetchall()
    return rows

for label, fn in [('current row-value', lambda c,l: paginate(con,'id','orders',l,c)[0]), ('split keyset', split_page)]:
    cursor=None; t=time.perf_counter(); pages=0
    for _ in range(1000):
        rows=fn(cursor,500)
        if not rows: break
        pages+=1
        cursor=Cursor(rows[-1]['created_at'],rows[-1]['id'])
    print(label,'pages',pages,'seconds',round(time.perf_counter()-t,4))
con.close(); os.remove(path)
